<script setup lang="ts">import {onMounted,ref} from 'vue';import {RouterLink,useRouter} from 'vue-router';import {ArrowRight,Truck,RotateCcw,ShieldCheck} from 'lucide-vue-next';import {api} from '../api';import type {Product} from '../stores';import ProductCard from '../components/ProductCard.vue';import {useCart,useSession,useUi} from '../stores';const products=ref<Product[]>([]),loading=ref(true),error=ref('');const session=useSession(),cart=useCart(),ui=useUi(),router=useRouter();onMounted(async()=>{try{products.value=(await api<{items:Product[]}>('/products?limit=4')).items}catch(e:any){error.value=e.message}finally{loading.value=false}});async function add(id:string){if(!session.user)return router.push('/login');try{await cart.add(id);ui.toast('Added to your shopping bag');ui.cartOpen=true}catch(e:any){ui.toast(e.message,'error')}}</script>
<template><main><section class="hero"><img src="https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1800&q=85" alt="Shopora seasonal collection"/><div class="hero-copy"><small>AUTUMN / WINTER COLLECTION 2026</small><h1>Refined Simplicity for Everyday Living.</h1><p>Discover meticulously crafted essentials designed to seamlessly elevate your lifestyle and home aesthetic.</p><div><RouterLink class="btn-light" to="/products">Explore Collection</RouterLink><RouterLink class="btn-outline" to="/products?category=fashion">View Lookbook</RouterLink></div></div></section><section class="container section-block"><header class="section-heading"><div><h2>Curated Categories</h2><p>Explore by curated design discipline</p></div></header><div class="category-grid"><RouterLink to="/products?category=fashion"><img src="https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=700&q=80"/><span><b>Apparel</b><small>Modern essentials</small></span></RouterLink><RouterLink to="/products?category=electronics"><img src="https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=700&q=80"/><span><b>Audio & Tech</b><small>Elevated utility</small></span></RouterLink><RouterLink to="/products?category=home-living"><img src="https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=700&q=80"/><span><b>Home Living</b><small>Considered spaces</small></span></RouterLink><RouterLink to="/products?category=accessories"><img src="https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=700&q=80"/><span><b>Accessories</b><small>Finishing details</small></span></RouterLink></div></section><section class="featured section-block"><div class="container"><header class="section-heading"><div><small>CURATED HIGHLIGHTS</small><h2>Featured Arrivals</h2></div><RouterLink to="/products">View All Products <ArrowRight :size="14"/></RouterLink></header><p v-if="error" class="alert error">{{error}}</p><div v-if="loading" class="product-grid"><div v-for="i in 4" class="skeleton product-skeleton"/></div><div v-else class="product-grid"><ProductCard v-for="p in products" :key="p.id" :product="p" @add="add"/></div></div></section><section class="container benefits"><div><span><Truck/></span><div><b>Nationwide Express Shipping</b><p>Dispatched within 24 hours with real-time tracking.</p></div></div><div><span><ShieldCheck/></span><div><b>Authenticity Guarantee</b><p>Directly sourced from certified craftspeople.</p></div></div><div><span><RotateCcw/></span><div><b>Hassle-Free Returns</b><p>30-day effortless exchange or refund policy.</p></div></div></section></main></template>
